/* id="insert" */
SELECT ACTIVITY_LOG_SEQ.NEXTVAL FROM DUAL
INSERT INTO ACTIVITY_LOG ( ACTIVITY_ID, MEMBER_ID, ACTIVITY_TYPE, ACTION_TYPE, TARGET_ID, TITLE, CREATED_AT ) VALUES ( #{activityId}, #{memberId}, #{activityType}, #{actionType}, #{targetId,jdbcType=NUMERIC}, #{title}, SYSTIMESTAMP )

mapper.select:
/* id="selectList" */ SELECT ACTIVITY_ID, MEMBER_ID, ACTIVITY_TYPE, ACTION_TYPE, TARGET_ID, TITLE, CREATED_AT FROM ACTIVITY_LOG WHERE MEMBER_ID = #{memberId}
AND ACTIVITY_TYPE = #{activityType}
ORDER BY CREATED_AT DESC, ACTIVITY_ID DESC
